contract InvMutTest {
    C c;
    event DummyDeposit(address indexed src, address indexed rcvr, uint256 assets, uint256 shares);

    constructor(C _c) { c = _c; }

    // Test calls deposit with arbitrary assets and receiver. We assert that either the call reverted,
    // or it returned non-negative shares and the Deposit event (emitted by c) matches the return.
    // Because we cannot directly capture logs here, we instead rely on the external observable effects:
    // - deposit returns a uint256 shares
    // - deposit emits a Deposit(address indexed sender, address indexed owner, uint256 assets, uint256 shares)
    // The test will call deposit and then verify a general relation between the returned shares and
    // convertToShares(asset) as a weak consistency property: if deposit succeeds, then convertToShares(assets)
    // should be either equal to or a valid conversion (non-zero when shares non-zero). This gives a general
    // property linking deposit return value to the public conversion function.

    // We make the rule general: for any assets and receiver, either deposit reverts or the returned shares
    // equal the view convertToShares(assets) OR both are zero. This ensures deposit aligns with the conversion logic.

    function run(uint256 assets, address receiver) public payable {
        require(address(this).balance >= 0, true); // no precondition on parameters

        bool reverted;
        uint256 retShares = 0;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            reverted = false;
            retShares = shares;
        } catch {
            reverted = true;
        }

        // Read the view conversion for the same assets
        uint256 convShares = c.convertToShares(assets);

        // General rule: if deposit succeeded then either retShares == convShares or both are zero.
        // This captures that deposit's result agrees with the contract's public conversion view.
        assert(reverted || (retShares == convShares || (retShares == 0 && convShares == 0)));
    }

    receive() external payable {}
}

