contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a caller address (which must be an authorized ward or not),
    // and a price to set. We can't change msg.sender when calling c from here; msg.sender for calls
    // will be this contract. So to test both authorized and unauthorized behavior we accept a
    // boolean `makeAuth` which, if true, first uses c.rely(address(this)) to authorize this contract
    // (this is allowed because constructor of C makes deployer an auth and the checker deploys a
    // fresh C and passes it to this test; however the test contract is not the deployer, so we
    // cannot assume we are already authorized. Therefore we try to call rely and catch revert to
    // record whether authorization succeeded). The rule asserts that if the call to updatePrice
    // succeeded (did not revert) then latestPrice equals the provided price and lastPriceUpdate > 0.

    function run(bool makeAuth, uint128 price) public payable {
        require(true);

        // Try to become authorized if requested. If we cannot rely (because not authorized), that's fine.
        bool becameAuth;
        try c.rely(address(this)) {
            becameAuth = true;
        } catch {
            becameAuth = false;
        }

        // Record previous values (observable only via public getters)
        uint128 prevPrice = c.latestPrice();
        uint256 prevLast = c.lastPriceUpdate();

        // Attempt to call updatePrice and capture revert status
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state values
        uint128 afterPrice = c.latestPrice();
        uint256 afterLast = c.lastPriceUpdate();

        // General rule (single assert):
        // If updatePrice call succeeded then contract's latestPrice must equal the input price
        // and lastPriceUpdate must be nonzero and at least as large as previous lastPriceUpdate.
        // If updatePrice call reverted then state must be unchanged w.r.t latestPrice and lastPriceUpdate.
        assert(
            (!reverted && afterPrice == price && afterLast > 0 && afterLast >= prevLast)
            || (reverted && afterPrice == prevPrice && afterLast == prevLast)
        );
    }

    receive() external payable {}
}

