contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing all interactions
    // params: assets to deposit and the receiver address
    function run(uint256 assets, address receiver) public payable {
        require(true);

        // read observable before-state
        uint256 totalSupplyBefore = c.totalSupply();

        // attempt deposit as a top-level state-changing call, capturing revert
        bool depositReverted;
        uint256 returnedShares;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            depositReverted = false;
            returnedShares = shares;
        } catch {
            depositReverted = true;
            returnedShares = 0;
        }

        // observe after-state and returned values via public surface
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule:
        // - if deposit reverted, totalSupply must be unchanged
        // - if deposit succeeded, totalSupply increases by at least 0 and the function returned the same shares value we captured
        //   and the Deposit event (emitted by C) would have assets==assets and shares==returnedShares; we cannot read events here,
        //   so we instead assert the function returned shares equals returnedShares and totalSupplyAfter >= totalSupplyBefore

        assert(
            (depositReverted && totalSupplyAfter == totalSupplyBefore)
            || (!depositReverted && totalSupplyAfter >= totalSupplyBefore && returnedShares == returnedShares)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take assets and receiver; require receiver == address(this) so withApproval passes (msg.sender must equal owner)
    // We will call previewDeposit (view) then attempt deposit and check relation.
    function run(uint256 assets, address receiver) public payable {
        // Precondition: we must be the receiver for the withApproval modifier to accept msg.sender == owner
        require(receiver == address(this));

        // Call the view preview first. It uses msg.sender (the caller) inside C.previewDeposit -> investmentManager.previewDeposit(msg.sender,...)
        // Since the InvMutTest contract is the caller of c.previewDeposit, and later deposit will be invoked by this contract as well,
        // the values should be comparable.
        uint256 previewShares;
        bool previewSucceeds = true;
        try c.previewDeposit(assets) returns (uint256 s) { previewShares = s; }
        catch { previewSucceeds = false; }

        // Now attempt the state-changing deposit call. It requires msg.sender == receiver due to withApproval modifier.
        // As receiver == address(this) this call should be allowed by modifier; it may still revert due to investment manager logic.
        bool depositReverted;
        uint256 depositShares = type(uint256).max;
        try c.deposit{value: 0}(assets, receiver) returns (uint256 s) { depositReverted = false; depositShares = s; }
        catch { depositReverted = true; }

        // General rule asserted:
        // If previewDeposit succeeded (did not revert) then the actual deposit must NOT revert and must return the same shares as preview.
        // This connects the view preview semantics to the state-changing behavior for the same caller.
        assert((!previewSucceeds) || (!depositReverted && depositShares == previewShares));
    }

    receive() external payable {}
}

