contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters that will be forwarded to deposit/mint/withdraw/redeem flows.
    // The test will: read totalAssets() before, attempt a deposit (which uses investmentManager.processDeposit),
    // catching whether it reverts; then read totalAssets() after and assert that if the manager returned 0
    // (observed via the returned shares/assets) then totalAssets didn't increase. Because we cannot call
    // the internal investmentManager directly, we perform operations and observe returned values.
    function run(uint256 assetsToDeposit, address receiverForDeposit, uint256 sharesToMint, address receiverForMint, uint256 assetsToWithdraw, address receiverForWithdraw, address ownerForWithdraw, uint256 sharesToRedeem, address receiverForRedeem, address ownerForRedeem) public payable {
        require(receiverForDeposit != address(0) && receiverForMint != address(0) && receiverForWithdraw != address(0) && receiverForRedeem != address(0));

        // Observe before totalAssets
        uint256 before = c.totalAssets();

        // Attempt deposit: it may revert due to withApproval (msg.sender must equal receiver), so call in a way
        // that typically reverts; we catch the revert flag and treat reverted as true. We still want to reach the assert.
        bool depositReverted;
        uint256 depositShares = type(uint256).max; // sentinel if call reverted
        try c.deposit(assetsToDeposit, receiverForDeposit) returns (uint256 s) {
            depositReverted = false;
            depositShares = s;
        } catch {
            depositReverted = true;
        }

        // Attempt mint
        bool mintReverted;
        uint256 mintAssets = type(uint256).max;
        try c.mint(sharesToMint, receiverForMint) returns (uint256 a) {
            mintReverted = false;
            mintAssets = a;
        } catch {
            mintReverted = true;
        }

        // Attempt withdraw
        bool withdrawReverted;
        uint256 withdrawShares = type(uint256).max;
        try c.withdraw(assetsToWithdraw, receiverForWithdraw, ownerForWithdraw) returns (uint256 s) {
            withdrawReverted = false;
            withdrawShares = s;
        } catch {
            withdrawReverted = true;
        }

        // Attempt redeem
        bool redeemReverted;
        uint256 redeemAssets = type(uint256).max;
        try c.redeem(sharesToRedeem, receiverForRedeem, ownerForRedeem) returns (uint256 a) {
            redeemReverted = false;
            redeemAssets = a;
        } catch {
            redeemReverted = true;
        }

        // Observe after totalAssets
        uint256 after = c.totalAssets();

        // General rule asserted: For any of the four operations that completed (did not revert) and returned 0
        // (meaning investmentManager processed zero assets/shares), the totalAssets() must not have increased.
        // We express this as: if any returned value is zero then after <= before. We avoid underflow by using comparisons.
        bool zeroReturnedImpliesNoIncrease = true;
        if (!depositReverted && depositShares == 0) zeroReturnedImpliesNoIncrease = zeroReturnedImpliesNoIncrease && (after <= before);
        if (!mintReverted && mintAssets == 0) zeroReturnedImpliesNoIncrease = zeroReturnedImpliesNoIncrease && (after <= before);
        if (!withdrawReverted && withdrawShares == 0) zeroReturnedImpliesNoIncrease = zeroReturnedImpliesNoIncrease && (after <= before);
        if (!redeemReverted && redeemAssets == 0) zeroReturnedImpliesNoIncrease = zeroReturnedImpliesNoIncrease && (after <= before);

        assert(zeroReturnedImpliesNoIncrease);
    }

    // No special receive logic needed
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters forwarded to the four ERC4626-like operations.
    // The test reads totalAssets() before, attempts each operation (catching reverts),
    // then reads totalAssets() after and asserts the general rule.
    function run(
        uint256 assetsToDeposit,
        address receiverForDeposit,
        uint256 sharesToMint,
        address receiverForMint,
        uint256 assetsToWithdraw,
        address receiverForWithdraw,
        address ownerForWithdraw,
        uint256 sharesToRedeem,
        address receiverForRedeem,
        address ownerForRedeem
    ) public payable {
        // require non-zero addresses for receivers/owners to avoid trivial reverts from zero-address logic
        require(receiverForDeposit != address(0) && receiverForMint != address(0) && receiverForWithdraw != address(0) && receiverForRedeem != address(0) && ownerForWithdraw != address(0) && ownerForRedeem != address(0));

        // Observe before totalAssets
        uint256 beforeTotal = c.totalAssets();

        // deposit
        bool depositReverted;
        uint256 depositShares = type(uint256).max;
        try c.deposit(assetsToDeposit, receiverForDeposit) returns (uint256 s) {
            depositReverted = false;
            depositShares = s;
        } catch {
            depositReverted = true;
        }

        // mint
        bool mintReverted;
        uint256 mintAssets = type(uint256).max;
        try c.mint(sharesToMint, receiverForMint) returns (uint256 a) {
            mintReverted = false;
            mintAssets = a;
        } catch {
            mintReverted = true;
        }

        // withdraw
        bool withdrawReverted;
        uint256 withdrawShares = type(uint256).max;
        try c.withdraw(assetsToWithdraw, receiverForWithdraw, ownerForWithdraw) returns (uint256 s) {
            withdrawReverted = false;
            withdrawShares = s;
        } catch {
            withdrawReverted = true;
        }

        // redeem
        bool redeemReverted;
        uint256 redeemAssets = type(uint256).max;
        try c.redeem(sharesToRedeem, receiverForRedeem, ownerForRedeem) returns (uint256 a) {
            redeemReverted = false;
            redeemAssets = a;
        } catch {
            redeemReverted = true;
        }

        // Observe after totalAssets
        uint256 afterTotal = c.totalAssets();

        // General rule: if any of the four calls completed (did not revert) and returned 0,
        // then totalAssets() must not have increased (afterTotal <= beforeTotal).
        bool ruleHolds = true;
        if (!depositReverted && depositShares == 0) { ruleHolds = ruleHolds && (afterTotal <= beforeTotal); }
        if (!mintReverted && mintAssets == 0) { ruleHolds = ruleHolds && (afterTotal <= beforeTotal); }
        if (!withdrawReverted && withdrawShares == 0) { ruleHolds = ruleHolds && (afterTotal <= beforeTotal); }
        if (!redeemReverted && redeemAssets == 0) { ruleHolds = ruleHolds && (afterTotal <= beforeTotal); }

        assert(ruleHolds);
    }

    receive() external payable {}
}

