        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule: if updatePrice did not revert, then latestPrice equals the input price
        // and lastPriceUpdate is >= beforeTs and equals current block timestamp (since updatePrice sets to block.timestamp)
