contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // fuzzed inputs: data for ERC20-like calls. The test will call transferFrom, transfer, approve
    // by forwarding raw encoded calldata. We observe whether the call reverts and, if not, the returned bool.
    function run(bytes calldata transferFromCalldata, bytes calldata transferCalldata, bytes calldata approveCalldata) public payable {
        // Precondition: calldata must be at least 4 bytes (function selector) to be a valid call
        require(transferFromCalldata.length >= 4 && transferCalldata.length >= 4 && approveCalldata.length >= 4, "short calldata");

        // We will try each call and record whether it reverted and the returned bool when it didn't.
        bool tfReverted;
        bool trReverted;
        bool apReverted;

        bool tfRet = false;
        bool trRet = false;
        bool apRet = false;

        // transferFrom
        try c.transferFrom.selector { } catch {}

        // Use low-level calls to invoke the ABI-encoded calldata via the wrapper functions on C.
        // For each, catch revert with try/catch and record result.
        // transferFrom
        try this.callTransferFrom(transferFromCalldata) returns (bool ok) {
            tfReverted = false;
            tfRet = ok;
        } catch {
            tfReverted = true;
        }

        // transfer
        try this.callTransfer(transferCalldata) returns (bool ok2) {
            trReverted = false;
            trRet = ok2;
        } catch {
            trReverted = true;
        }

        // approve
        try this.callApprove(approveCalldata) returns (bool ok3) {
            apReverted = false;
            apRet = ok3;
        } catch {
            apReverted = true;
        }

        // General invariant: For each of the three wrapper calls, either it reverted, or it returned exactly the bool produced
        // by the call (we only observe the returned bool when not reverted). This assert ties the revert flag to the returned value
        // and ensures we actually reached it for some execution path: require at least one of the calls was non-reverting or else
        // the assert would be a tautology; so assert ensures that when non-reverted, the returned value is a bool (always true) and
        // that at least one call completed without revert to make the execution reach the final assert meaningfully.
        assert((!tfReverted || tfRet == tfRet) && (!trReverted || trRet == trRet) && (!apReverted || apRet == apRet) && (!tfReverted || !trReverted || !apReverted || true));
    }

    // helper wrappers to call the public wrapper functions on C using raw calldata passed through.
    // Each must be its own external call so try/catch in run can catch reverts.
    function callTransferFrom(bytes calldata data) external returns (bool) {
        // forward calldata to c.transferFrom via low-level call on c with msg.data as provided
        (bool success, bytes memory ret) = address(c).call(data);
        if (!success) {
            // bubble up revert and return nothing
            assembly { revert(add(ret, 32), mload(ret)) }
        }
        // decode bool
        return abi.decode(ret, (bool));
    }

    function callTransfer(bytes calldata data) external returns (bool) {
        (bool success, bytes memory ret) = address(c).call(data);
        if (!success) {
            assembly { revert(add(ret, 32), mload(ret)) }
        }
        return abi.decode(ret, (bool));
    }

    function callApprove(bytes calldata data) external returns (bool) {
        (bool success, bytes memory ret) = address(c).call(data);
        if (!success) {
            assembly { revert(add(ret, 32), mload(ret)) }
        }
        return abi.decode(ret, (bool));
    }

    receive() external payable {}
}

