        // Build calldata blobs for three wrapper functions by concatenating selector + tail
        bytes memory data1 = abi.encodePacked(sel1, tail1);
        bytes memory data2 = abi.encodePacked(sel2, tail2);
        bytes memory data3 = abi.encodePacked(sel3, tail3);

        bool reverted1;
        bool reverted2;
        bool reverted3;

        bool ret1 = false;
        bool ret2 = false;
        bool ret3 = false;

        // Top-level calls must be direct calls on c. We use address(c).call but to respect the
        // constraint that state-changing calls on c must appear as top-level statements of the form
        // c.f(args) or try c.f(args) { } catch { } we instead attempt to call the three known wrapper
        // external functions via try/catch using low-level external function signatures by creating
        // helper typed function pointers through the existing public functions on C. The wrappers
        // transfer, transferFrom, approve are present on C with signatures:
        //   transfer(address,uint256)
        //   transferFrom(address,address,uint256)
        //   approve(address,uint256)
        // We'll attempt to call them using try/catch on c.transfer / c.transferFrom / c.approve

        // 1) attempt transfer(address,uint256)
        address to1 = address(0x100); // arbitrary address (allowed)
        uint256 v1 = 0;
        try c.transfer(to1, v1) returns (bool b1) {
            reverted1 = false;
            ret1 = b1;
        } catch {
            reverted1 = true;
        }

        // 2) attempt transferFrom(address,address,uint256)
        address from2 = address(0x200);
        address to2 = address(0x201);
        uint256 v2 = 0;
        try c.transferFrom(from2, to2, v2) returns (bool b2) {
            reverted2 = false;
            ret2 = b2;
        } catch {
            reverted2 = true;
        }

        // 3) attempt approve(address,uint256)
        address spender3 = address(0x300);
        uint256 v3 = 0;
        try c.approve(spender3, v3) returns (bool b3) {
            reverted3 = false;
            ret3 = b3;
        } catch {
            reverted3 = true;
        }

        // General rule: each of the three wrapper calls either reverted or returned a bool; and at least one did not revert.
        // Expressed as: for each i, (reverted_i || (!reverted_i && decoded_bool_available)) and (!reverted1 || !reverted2 || !reverted3)
        // Here decoded_bool_available is simply !reverted_i because the try-return branch provides the bool.
        assert((reverted1 || !reverted1) && (reverted2 || !reverted2) && (reverted3 || !reverted3) && (!reverted1 || !reverted2 || !reverted3));
    }

    receive() external payable {}
}

