contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function drives c and asserts the general invariant
    function run(address caller, uint128 price) public payable {
        require(caller != address(0));

        // Ensure this test contract is initially authorized so it can call file/rely if needed.
        // The deployer of C is authorized (wards[msg.sender]=1) but here msg.sender is the deployer of InvMutTest.
        // We attempt to set authorization for this contract by calling c.file to set investmentManager only if possible.
        // However file is protected by auth; instead rely on trying updatePrice both as authorized and unauthorized.

        // First: try calling updatePrice() as this contract (msg.sender = InvMutTest). We record whether it reverts.
        bool revertedByTest;
        try c.updatePrice(price) {
            revertedByTest = false;
        } catch {
            revertedByTest = true;
        }

        // Now attempt to perform updatePrice via a low-level call from 'caller'.
        // We simulate that by calling c.updatePrice through a static call from this contract but encoding the msg.sender isn't possible.
        // Instead, we check the observable effect: if our first call succeeded (not reverted), then latestPrice must equal price
        // and lastPriceUpdate must be set to a non-zero value (timestamp when called). If it reverted, these must not reflect the new price.

        uint128 observedPrice = c.latestPrice();
        uint256 observedTimestamp = c.lastPriceUpdate();

        // If updatePrice succeeded, latestPrice must equal the input price and lastPriceUpdate must be non-zero and recent (<= block.timestamp).
        // If it reverted, then either latestPrice differs from price or lastPriceUpdate is unchanged (could be zero).
        // We express this as a single assert: (revertedByTest implies latestPrice != price OR observedTimestamp == 0)
        // AND (!revertedByTest implies latestPrice == price AND observedTimestamp != 0 AND observedTimestamp <= block.timestamp)

        assert(
            (revertedByTest && (observedPrice != price || observedTimestamp == 0))
            ||
            (!revertedByTest && observedPrice == price && observedTimestamp != 0 && observedTimestamp <= block.timestamp)
        );
    }

    receive() external payable {}
}

