contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that performs the test. We take a candidate price and an address
    // that will be used as the caller for updatePrice via delegated call simulation:
    // since the checker runs the test with msg.sender = this contract and this contract
    // deployed c, it is authorized (wards[msg.sender] == 1) initially. We also allow a flag
    // `useAuth` to choose whether to call updatePrice directly (authorized) or attempt to
    // simulate an unauthorized call by first calling c.deny(address(this)) then calling
    // updatePrice (which should revert). The rule asserts the two possible outcomes.
    function run(uint128 price, bool expectAuthorized) public payable {
        require(true);

        // read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        bool reverted;
        // If expectAuthorized==true, ensure this contract is authorized and call updatePrice
        if (expectAuthorized) {
            // authorize this contract (constructor of C already did, but re-rely to be explicit)
            // rely is auth-only; since constructor set wards[msg.sender]==1 for the deployer of C,
            // and that deployer is this contract, calling rely should succeed.
            c.rely(address(this));
            reverted = false;
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // make sure this contract is denied and then try updatePrice which should revert
            c.deny(address(this));
            reverted = false;
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // General rule:
        // - If call was expected authorized, it must NOT revert, latestPrice must equal price,
        //   and lastPriceUpdate must be >= beforeTimestamp and equal to block.timestamp of the call.
        //   We cannot directly access the exact block.timestamp used by C, but afterTimestamp must be >= beforeTimestamp.
        // - If call was expected unauthorized, the call must revert and state must be unchanged.
        assert(
            (expectAuthorized && !reverted && afterPrice == price && afterTimestamp >= beforeTimestamp)
            || (!expectAuthorized && reverted && afterPrice == beforePrice && afterTimestamp == beforeTimestamp)
        );
    }

    receive() external payable {}
}

