    // single public entry: test a family of withApproval-protected functions
    // params: selector to choose which withApproval function to call, an amount, and an owner address
    function run(uint8 selector, uint256 amount, address owner) public payable {
        // selector values we support:
        // 0 = deposit(assets, receiver)
        // 1 = mint(shares, receiver)
        // 2 = withdraw(assets, receiver, owner)
        // 3 = redeem(shares, receiver, owner)
        // 4 = requestDeposit(assets, owner)
        // 5 = requestRedeem(shares, owner)
        // 6 = decreaseDepositRequest(assets, owner)
        // 7 = decreaseRedeemRequest(shares, owner)

        require(selector <= 7, "sel");

        // call the chosen function and record whether it reverted
        bool reverted;
        if (selector == 0) {
            try c.deposit(amount, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (selector == 1) {
            try c.mint(amount, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (selector == 2) {
            try c.withdraw(amount, owner, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (selector == 3) {
            try c.redeem(amount, owner, owner) returns (uint256) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (selector == 4) {
            try c.requestDeposit(amount, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (selector == 5) {
            try c.requestRedeem(amount, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (selector == 6) {
            try c.decreaseDepositRequest(amount, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else { // selector == 7
            try c.decreaseRedeemRequest(amount, owner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // The general rule: these functions are protected by withApproval(owner) which requires msg.sender == owner.
        // Since this test contract is the msg.sender for all calls, the call must succeed exactly when owner == address(this).
        assert(reverted == (owner != address(this)));
    }

    receive() external payable {}
 }

