contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: (1) deposit/ mint / withdraw / redeem when called by this contract with withApproval enforcement
    // (2) the pool's view conversion functions and totalAssets do not revert
    // (3) calls requiring withApproval revert when msg.sender != owner (we emulate by calling with an owner param not equal to address(this))
    // The single assert encodes a general invariant over observed return values and revert flags.

    function run(address receiver, address owner, uint256 assets, uint256 shares) public payable {
        require(receiver != address(0) && owner != address(0));

        // Read-only calls that must not revert and provide observable values
        // These are view calls; if any revert they'd bubble and fail the test invocation
        uint256 totalBefore = c.totalAssets();
        // conversion views
        uint256 convShares = c.convertToShares(assets);
        uint256 convAssets = c.convertToAssets(shares);
        uint256 maxDep = c.maxDeposit(receiver);
        uint256 maxMin = c.maxMint(receiver);
        uint256 maxW = c.maxWithdraw(receiver);
        uint256 maxR = c.maxRedeem(receiver);

        bool depositReverted;
        bool mintReverted;
        bool withdrawReverted;
        bool redeemReverted;

        // Attempt deposit: deposit has withApproval(receiver) so it will succeed only when msg.sender == receiver
        // Here msg.sender is this contract; so if receiver == address(this) it should not revert, otherwise it should revert
        try c.deposit{value: 0}(assets, receiver) returns (uint256 outShares) {
            depositReverted = false;
            // outShares must be a non-negative uint (always true) but we record it
            // Ensure that returned shares equal the view convertToShares(assets) OR at least do not exceed some unreasonable bound:
            // We will observe it via a read-only conversion again and check consistency below
            convShares = outShares;
        } catch {
            depositReverted = true;
        }

        // mint
        try c.mint(shares, receiver) returns (uint256 outAssets) {
            mintReverted = false;
            convAssets = outAssets;
        } catch {
            mintReverted = true;
        }

        // withdraw(owner) requires msg.sender == owner via withApproval(owner)
        try c.withdraw(assets, receiver, owner) returns (uint256 outSharesRedeemed) {
            withdrawReverted = false;
            // update convShares to observed redeemed shares
            convShares = outSharesRedeemed;
        } catch {
            withdrawReverted = true;
        }

        // redeem
        try c.redeem(shares, receiver, owner) returns (uint256 outAssetsPayout) {
            redeemReverted = false;
            convAssets = outAssetsPayout;
        } catch {
            redeemReverted = true;
        }

        // Also test requestDeposit/requestRedeem which require withApproval(owner)
        bool reqDepReverted;
        bool reqRedReverted;
        try c.requestDeposit(assets, owner) { reqDepReverted = false; } catch { reqDepReverted = true; }
        try c.requestRedeem(shares, owner) { reqRedReverted = false; } catch { reqRedReverted = true; }

        // General rule asserted:
        // - If receiver == address(this) then deposit and mint SHOULD NOT revert (since withApproval(receiver) passes), otherwise they may revert.
        // - If owner == address(this) then withdraw and redeem SHOULD NOT revert, otherwise they may revert.
        // - The view totalAssets remains a uint and we require consistency that it is >= 0 and does not decrease as a result of view calls above (we only did views earlier so totalBefore is unchanged)
        // Encode these as a single boolean formula combining the observed revert flags and parameter relationships.

        assert(
            // consistency for deposit/mint withApproval
            (receiver == address(this) ? depositReverted == false : true)
            && (receiver == address(this) ? mintReverted == false : true)
            // consistency for withdraw/redeem withApproval
            && (owner == address(this) ? withdrawReverted == false : true)
            && (owner == address(this) ? redeemReverted == false : true)
            // requests also follow withApproval same owner rule
            && (owner == address(this) ? reqDepReverted == false : true)
            && (owner == address(this) ? reqRedReverted == false : true)
            // all observed conversion outputs and total must be non-negative (always true for uints) and totalBefore matches a subsequent view call
            && (totalBefore == c.totalAssets())
        );
    }

    receive() external payable {}
}

