    // single public entry used by the checker
    function run(uint256 assets, address receiver) public payable {
        // precondition: function must be callable; no extra preconditions on inputs
        require(true);

        // We will call convertToShares view beforehand to observe expected shares.
        // Note: convertToShares is a view that calls investmentManager.convertToShares(...)
        uint256 expectedShares = c.convertToShares(assets);

        // Try calling deposit; deposit has modifier withApproval(receiver) which requires msg.sender == receiver.
        // Here msg.sender is this contract, so deposit will revert unless receiver == address(this).
        bool reverted;
        uint256 returnedShares = type(uint256).max;
        try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
        }

        // Observe some view after: totalAssets is always available
        uint256 totAssets = c.totalAssets();

        // General rule: if deposit did not revert then the returned shares must equal convertToShares(assets)
        // and totalAssets is a uint256 (non-negative). If deposit reverted then it must be because msg.sender != receiver
        // which we can detect: when not reverted, receiver must equal address(this) due to withApproval modifier.
        assert(
            (reverted && receiver != address(this)) ||
            (!reverted && receiver == address(this) && returnedShares == expectedShares && totAssets >= 0)
        );
    }

    receive() external payable {}
}

