contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // params choose a target owner and values; msg.sender for calls to c will be this contract
    function run(address owner, uint256 assets, uint256 shares) public payable {
        require(owner != address(0));

        // We will call four functions that are protected by withApproval(owner):
        // deposit(assets, receiver), mint(shares, receiver), withdraw(... owner), redeem(... owner)
        // Also requestDeposit/requestRedeem and decreaseDepositRequest/decreaseRedeemRequest are withApproval.
        // For each, we check whether the call reverts when owner != msg.sender and succeeds when owner == msg.sender.

        bool revert_deposit_notOwner;
        bool revert_mint_notOwner;
        bool revert_requestDeposit_notOwner;
        bool revert_requestRedeem_notOwner;
        bool revert_withdraw_notOwner;
        bool revert_redeem_notOwner;

        // calls where msg.sender (this contract) is NOT the owner parameter: should revert
        try c.deposit{value: 0}(assets, owner) {
            revert_deposit_notOwner = false;
        } catch {
            revert_deposit_notOwner = true;
        }

        try c.mint(shares, owner) {
            revert_mint_notOwner = false;
        } catch {
            revert_mint_notOwner = true;
        }

        try c.requestDeposit(assets, owner) {
            revert_requestDeposit_notOwner = false;
        } catch {
            revert_requestDeposit_notOwner = true;
        }

        try c.requestRedeem(shares, owner) {
            revert_requestRedeem_notOwner = false;
        } catch {
            revert_requestRedeem_notOwner = true;
        }

        try c.withdraw(assets, owner, owner) {
            revert_withdraw_notOwner = false;
        } catch {
            revert_withdraw_notOwner = true;
        }

        try c.redeem(shares, owner, owner) {
            revert_redeem_notOwner = false;
        } catch {
            revert_redeem_notOwner = true;
        }

        // Now, to observe the opposite case (where msg.sender == owner), we need to simulate calls coming from owner.
        // The checker runs this single transaction where msg.sender is the test contract; we cannot change msg.sender.
        // However, C's constructor set wards[msg.sender]=1 for deployer; the withApproval modifier only checks msg.sender==owner.
        // We can exploit that supplying owner == address(this) should allow the calls to succeed (no revert).

        bool revert_deposit_owner;
        bool revert_mint_owner;
        bool revert_requestDeposit_owner;
        bool revert_requestRedeem_owner;
        bool revert_withdraw_owner;
        bool revert_redeem_owner;

        // owner == address(this)
        address self = address(this);

        try c.deposit{value: 0}(assets, self) {
            revert_deposit_owner = false;
        } catch {
            revert_deposit_owner = true;
        }

        try c.mint(shares, self) {
            revert_mint_owner = false;
        } catch {
            revert_mint_owner = true;
        }

        try c.requestDeposit(assets, self) {
            revert_requestDeposit_owner = false;
        } catch {
            revert_requestDeposit_owner = true;
        }

        try c.requestRedeem(shares, self) {
            revert_requestRedeem_owner = false;
        } catch {
            revert_requestRedeem_owner = true;
        }

        try c.withdraw(assets, self, self) {
            revert_withdraw_owner = false;
        } catch {
            revert_withdraw_owner = true;
        }

        try c.redeem(shares, self, self) {
            revert_redeem_owner = false;
        } catch {
            revert_redeem_owner = true;
        }

        // General rule: for each withApproval-protected function f, the call should revert when owner != msg.sender
        // and should NOT revert when owner == msg.sender. We assert that property for all tested functions.
        assert(
            (revert_deposit_notOwner && !revert_deposit_owner)
            && (revert_mint_notOwner && !revert_mint_owner)
            && (revert_requestDeposit_notOwner && !revert_requestDeposit_owner)
            && (revert_requestRedeem_notOwner && !revert_requestRedeem_owner)
            && (revert_withdraw_notOwner && !revert_withdraw_owner)
            && (revert_redeem_notOwner && !revert_redeem_owner)
        );
    }

    receive() external payable {}
}

