contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public entry that will be used by the prover
    // params: price to set, an address that we will attempt to authorize (as msg.sender for rely/deny calls)
    function run(uint128 price, address user) public payable {
        require(true);

        // Initially msg.sender of calls to c will be this contract.
        // The contract deployed c and has wards[msg.sender]==1 from C constructor, so this contract is authorized.
        // Record previous values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTime = c.lastPriceUpdate();

        // Call updatePrice as authorized caller (this contract). It must not revert and must set values.
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTime = c.lastPriceUpdate();

        // Now attempt to delegating authorization change: call rely(user) to give 'user' auth, then revoke it.
        // These actions are performed by this contract (authorized) and must succeed.
        c.rely(user);
        // After giving auth to user, ensure that the contract still can update price again successfully
        bool reverted2;
        try c.updatePrice(price) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }

        // Revoke the user's authorization
        c.deny(user);

        // General rule asserted:
        // If the first updatePrice call did not revert then latestPrice equals the input price and lastPriceUpdate is >= previous lastPriceUpdate and nonzero.
        // Also, authorized caller (this contract) can still call updatePrice afterwards (reverted2 == false).
        assert((reverted == false && afterPrice == price && afterTime != 0 && afterTime >= beforeTime && reverted2 == false) || (reverted == true && !(afterPrice == price && afterTime != 0)));
    }

    receive() external payable {}
}

