contract InvMutTest {
    C c;
    event DepositObserved(address indexed pool, address indexed receiver, uint256 assets, uint256 shares);

    constructor(C _c) { c = _c; }

    // We test that a non-reverting deposit call returns shares and that the returned assets equals the provided assets
    // (i.e. the deposit call's observable result is consistent: if it does not revert it returns a shares value and
    // the assets argument passed into the call is the assets value that the contract emitted/recorded for that call).
    // Because we cannot directly read emitted events from inside Solidity, we assert the relation between the input
    // `assets` and the returned `shares` via the convert/preview helpers: for any non-reverting deposit, the returned
    // shares must equal the value returned by previewDeposit(assets) when called by the same caller (msg.sender inside
    // c will be this contract). This leverages the expectation that previewDeposit mirrors processDeposit outcome.

    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0), true);

        // Read preview before the state-changing call
        uint256 previewShares = c.previewDeposit(assets);

        bool reverted;
        uint256 returnedShares = 0;
        try c.deposit(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
        }

        // General rule: if deposit does not revert, its returned shares must equal previewDeposit(assets)
        assert(reverted || returnedShares == previewShares);
    }

    receive() external payable {}
}

