contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: if deposit(assets, receiver) called by this contract does NOT revert,
    // then its returned shares equal the previewDeposit(assets) value observed before the call
    // (previewDeposit is a view that uses msg.sender; here it will use this contract).
    function run(uint256 assets, address receiver) public payable {
        require(true);

        // Read preview before making the state-changing call
        uint256 previewShares = c.previewDeposit(assets);

        bool reverted;
        uint256 returnedShares;
        try c.deposit(assets, receiver) {
            reverted = false;
            // deposit returns (uint256 shares)
            // But in try without return value we cannot capture it; instead call in a different try form
        } catch {
            reverted = true;
        }

        // To capture the returned value when not reverted, call deposit again only if it previously succeeded would be impossible.
        // Instead, perform the call with low-level call to capture the return when it doesn't revert.
        // Build calldata for deposit(uint256,address)
        bytes memory sig = abi.encodeWithSignature("deposit(uint256,address)", assets, receiver);
        (bool ok, bytes memory data) = address(c).call(sig);
        if (ok) {
            // decode returned uint256
            returnedShares = abi.decode(data, (uint256));
            reverted = false;
        } else {
            reverted = true;
        }

        // General rule: if call did not revert, returnedShares equals previewShares
        assert(reverted || returnedShares == previewShares);
    }

    receive() external payable {}
}

