    // single public entry performing the property test
    function run(uint128 price, address maybeAuth) public payable {
        require(price != 0 || true);
        // record previous observable values
        uint128 prevPrice = c.latestPrice();
        uint256 prevTs = c.lastPriceUpdate();

        // Try to call updatePrice from maybeAuth by invoking via c.file to grant/revoke auth
        // First, ensure maybeAuth is either authorized or not by using c.rely/c.deny from this contract (constructor of C made deployer authorized, but here msg.sender is this test contract)
        // We cannot call rely/deny because they require auth and this contract is not necessarily authorized. Instead, we branch by attempting the call directly from this contract (msg.sender for c.updatePrice will be this contract). 
        // We perform the call and observe whether it reverts.
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call attempt, read the public observables again
        uint128 newPrice = c.latestPrice();
        uint256 newTs = c.lastPriceUpdate();

        // General rule:
        // - If the call reverted, latestPrice and lastPriceUpdate must be unchanged.
        // - If the call succeeded, latestPrice must equal the provided price and lastPriceUpdate must be >= previous timestamp.
        assert(reverted ? (newPrice == prevPrice && newTs == prevTs) : (newPrice == price && newTs >= prevTs));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property test
    // params: assets to deposit and a receiver address (must be the same as msg.sender of c.deposit, so we pass an arbitrary address)
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));

        // Observe before-values via public getters
        uint256 beforeTotalAssets = c.totalAssets();
        uint256 beforeTotalSupply = c.totalSupply();

        // Attempt deposit as this contract; the C.deposit requires msg.sender == receiver due to withApproval modifier
        // so to simulate both revert and success cases, we call with receiver equal to address(this) or not via parameter.
        bool reverted;
        uint256 returnedShares;
        if (receiver == address(this)) {
            // This will satisfy withApproval and might succeed or revert depending on InvestmentManager
            try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
                reverted = false;
                returnedShares = shares;
            } catch {
                reverted = true;
                returnedShares = 0;
            }
        } else {
            // This will fail the withApproval check and must revert immediately
            try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
                reverted = false;
                returnedShares = shares;
            } catch {
                reverted = true;
                returnedShares = 0;
            }
        }

        // Observe after-values
        uint256 afterTotalAssets = c.totalAssets();
        uint256 afterTotalSupply = c.totalSupply();

        // General rule asserted:
        // - If the deposit call reverted, totalAssets and totalSupply must be unchanged.
        // - If the deposit call succeeded, it must not cause both totalAssets and totalSupply to decrease simultaneously.
        assert(reverted ? (afterTotalAssets == beforeTotalAssets && afterTotalSupply == beforeTotalSupply)
                         : !(afterTotalAssets < beforeTotalAssets && afterTotalSupply < beforeTotalSupply));
    }

    receive() external payable {}
}

